import{_ as r,C as o,o as l,c as n,ag as a,E as s}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Seller & Product Flagging","description":"","frontmatter":{},"headers":[],"relativePath":"moderation/seller-product-flagging.md","filePath":"moderation/seller-product-flagging.md","lastUpdated":1786121967000}'),g={name:"moderation/seller-product-flagging.md"};function i(d,e,c,p,m,u){const t=o("ImagePopup");return l(),n("div",null,[e[0]||(e[0]=a('<h1 id="seller-product-flagging" tabindex="-1">Seller &amp; Product Flagging <a class="header-anchor" href="#seller-product-flagging" aria-label="Permalink to &quot;Seller &amp; Product Flagging&quot;">​</a></h1><p>Flagging lets customers report a problem with a <strong>product</strong> or a <strong>seller</strong> — a wrong, damaged, duplicate, or overpriced listing, or an issue with the seller. The admin defines the reasons customers can choose and reviews the flags that come in.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What customers can flag, and the rules around it</li><li>How the admin defines flag reasons</li><li>Where flags are reviewed, and the red-flag limit</li></ul></div><h2 id="who-can-flag" tabindex="-1">Who can flag <a class="header-anchor" href="#who-can-flag" aria-label="Permalink to &quot;Who can flag&quot;">​</a></h2><p>Like reviews, a flag can only be raised by a customer who has <strong>ordered</strong> the product (or from the seller), and each customer can flag a given product or seller <strong>once</strong> — which keeps flags meaningful rather than noise.</p><h2 id="flag-reasons-admin" tabindex="-1">Flag reasons (admin) <a class="header-anchor" href="#flag-reasons-admin" aria-label="Permalink to &quot;Flag reasons (admin)&quot;">​</a></h2><p>The admin controls the list of reasons a customer may pick when flagging. In the admin panel, go to <strong>Marketplace → Configure → Flag Reasons</strong>.</p>',7)),s(t,{src:"/images/seller-product-flagging/flag-reasons.png",alt:"Flag reasons list"}),e[1]||(e[1]=a("<p>Each reason has a <strong>type</strong> — <strong>Product</strong> or <strong>Seller</strong> — and a <strong>status</strong>:</p><ul><li><strong>Product</strong> reasons apply to a listing, e.g. <em>Receive wrong product</em>, <em>Missing product parts</em>, <em>Damaged product</em>, <em>Poor product quality</em>.</li><li><strong>Seller</strong> reasons apply to the seller, e.g. <em>Wrong product sold by seller</em>, <em>Over price product sold by seller</em>, <em>Duplicate product sold</em>.</li></ul><p>Use <strong>Create Reason</strong> to add one — an <strong>admin name</strong>, per-language <strong>labels</strong>, a <strong>type</strong> (Product or Seller), and a <strong>status</strong> — and edit, delete, enable, or disable reasons to control what customers can pick.</p>",3)),s(t,{src:"/images/seller-product-flagging/reason-create.png",alt:"Create flag reason form"}),e[2]||(e[2]=a('<h2 id="reviewing-flags-admin" tabindex="-1">Reviewing flags (admin) <a class="header-anchor" href="#reviewing-flags-admin" aria-label="Permalink to &quot;Reviewing flags (admin)&quot;">​</a></h2><p>When customers flag products or sellers, the admin reviews them:</p><ul><li><strong>Product flags</strong> — from <strong>Marketplace → Catalog → Products</strong>, a product&#39;s flags list shows who raised each flag, their email, the reason, and the date.</li><li><strong>Seller flags</strong> — from <strong>Marketplace → Sellers</strong>, a seller&#39;s flags list shows the same.</li></ul><h2 id="flag-settings-admin" tabindex="-1">Flag settings (admin) <a class="header-anchor" href="#flag-settings-admin" aria-label="Permalink to &quot;Flag settings (admin)&quot;">​</a></h2><p>Whether flagging is available at all, and how it&#39;s scored, is controlled in the system configuration under <strong>Configure → Marketplace → Moderation</strong> — a separate place from the reason list above. It has two sub-sections:</p><ul><li><strong>Product Flags</strong> — an <strong>Enable Flag</strong> toggle that turns product flagging on or off.</li><li><strong>Seller Flags</strong> — an <strong>Enable Flag</strong> toggle, plus <strong>Show Red Flag</strong> and a <strong>Red Flag Limit</strong>. Once a seller collects more flags than the limit, a red flag is shown on their profile, and flags feed into the seller&#39;s <a href="/sellers/seller-account-health">account health</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">Two different places</p><p>The <em>list of reasons</em> customers pick from lives under <strong>Marketplace → Configure → Flag Reasons</strong> (a management page inside the Marketplace section). The <em>flag settings</em> — turning flagging on and setting the red-flag limit — live under the system <strong>Configure → Marketplace → Moderation</strong>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep your reasons specific and few — a short, clear list gets more useful reports than a long, overlapping one.</p></div>',8))])}const _=r(g,[["render",i]]);export{f as __pageData,_ as default};
